    const hGroups = []; days.forEach((dn, i) => { const tm = time(i), last = hGroups[hGroups.length - 1]; if (last && last.time === tm && last.end === i - 1) { last.end = i; last.idx.push(i); } else hGroups.push({ start: i, end: i, time: tm, idx: [i] }); });
    hGroups.forEach(g => { const td = g.idx.includes(today); g.days = g.start === g.end ? days[g.start] : days[g.start] + ' – ' + days[g.end]; g.isToday = td; g.font = td ? "800 16px 'Figtree',sans-serif" : "500 16px 'Figtree',sans-serif"; g.color = td ? '#1C1C1C' : '#696F6A'; });
    const HS = 480, HE = 1560, hp = x => Math.max(0, Math.min(100, (x - HS) / (HE - HS) * 100)).toFixed(2) + '%';
    const hTicks = [[720, '12 PM'], [1080, '6 PM'], [1440, '12 AM']].map(k => ({ left: hp(k[0]), label: k[1] }));
    const hBars = days.map((d, i) => { const [a, b] = HR(i), td = i === today; return { day: d, time: time(i), left: hp(a), width: ((b - a) / (HE - HS) * 100).toFixed(2) + '%', barBg: td ? (isOpen ? t.btn : '#9A9F9B') : 'color-mix(in srgb, ' + t.btn + ' 28%, #fff)', rowBg: td ? t.tint : 'transparent', isToday: td, fontS: td ? "800 13px 'Figtree',sans-serif" : "500 13px 'Figtree',sans-serif", color: td ? '#1C1C1C' : '#696F6A', sx: m ? 1 : 0, delay: (0.25 + i * 0.05) + 's' }; });
    const nowAdj = nowM < 240 ? nowM + 1440 : nowM, nowLeft = hp(nowAdj), nowCol = isOpen ? t.btn : '#696F6A';
    const dur = x => x >= 60 ? Math.round(x / 60) + (Math.round(x / 60) === 1 ? ' hour' : ' hours') : x + ' min';
    const openSub = isOpen ? 'Closes in ' + dur(ob - nowM) : nowM < oa ? 'Opens in ' + dur(oa - nowM) : 'Closed for today';
    return { ...embVals, dirUrl, reviewsUrl: dirUrl, backHref: '/' + s.city + '/restaurants', certShow: tk === 'c', openLbl: isOpen ? 'Open now' : 'Closed', openHead, openSub, hGroups, hTicks, hBars, nowLeft, nowCol, openBg: isOpen ? '#E6F2E2' : '#EEEEEC', openFg: isOpen ? '#1F6B12' : '#5F6460', playLabel: s.playing ? 'Pause video' : 'Play video',
      call: () => { if (R.phone) { location.href = 'tel:' + String(R.phone).replace(/[^\d+]/g, ''); return; } toast('Phone numbers aren’t listed yet. Directions opens ' + R.name + ' on Google Maps, where their number is usually listed.'); },
      certNote: () => toast('Certificate scans are coming soon. You can ask to see it at the counter.'),
      toReviews: () => { const el = document.querySelector('[data-reviews]'); if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' }); },
      T: { ...t, NAME: t.name.toUpperCase() }, R, reel, clauses, reviews, reviews3: reviews.slice(0, 3), hours, hoursD, photosA, photosB, photosC,
      progD: mk('d', true), progM: mk('m', false), segs: [{ fill: '0%', active: true, onClick: () => this.go() }], gallery, thumbsC,
      reelZoom: s.playing ? 'scale(1.12)' : 'scale(1)',
      togglePlay: () => this.setState(st => ({ playing: !st.playing })),
      sheetToggle: e => { const el = e && e.currentTarget, sc = (el && el.closest('[data-detail-overlay]')) || document.scrollingElement; if (!sc) return; const open = sc.scrollTop > 40; sc.scrollTo({ top: open ? 0 : Math.max(0, window.innerHeight - 236 - 70), behavior: 'smooth' }); },
      pauseOp: s.playing ? 0 : 1, pauseTf: s.playing ? 'scale(.6)' : 'scale(1)',
      toggleLike: () => this.setState(st => ({ liked: !st.liked })),
      likeTf: s.liked ? 'scale(1.25)' : 'scale(1)', likeFill: s.liked ? '#B8835A' : 'none', likeStroke: s.liked ? '#B8835A' : '#fff', likes: s.liked ? '2,419' : '2,418',
      toggleSave: () => this.setState(st => ({ saved: !st.saved })),
      saveTf: s.saved ? 'scale(1.15) rotate(-8deg)' : 'none', saveFillW: s.saved ? '#fff' : 'none',
      sealTf: m ? 'rotate(-8deg) scale(1)' : 'rotate(-40deg) scale(.4)',
      inOp: m ? 1 : 0, inTf: m ? 'none' : 'translateY(40px)', reelInA: m ? 'rotate(2deg)' : 'translateY(80px) rotate(8deg)',
      pinTf: m ? 'translateY(0)' : 'translateY(-90px)'
    };
